/* eslint-disable @typescript-eslint/no-unused-vars -- port of the team's closure: dead locals and shapes stay as delivered */
// Literal port of the team's Casa3DSDK (module materials/textures). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installMaterialsTextures(K: Kernel, _shared: Shared): void {
  const { DOC, THREE, cfg } = K;
  // ---- materials ----
  function texture(n, f, rep = true, rx = 1, ry = 1) { const c = DOC.createElement('canvas'); c.width = n; c.height = n; const g = c.getContext('2d'); f(g, n); const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; if (rep) t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 4; return t; }
  const rngTexture = (s => () => (s = (s * 16807) % 2147483647) / 2147483647)(1234);
  const TEXGEN = {
    roughcast: () => texture(256, (g, n) => { g.fillStyle = '#e6e6e6'; g.fillRect(0, 0, n, n); for (let i = 0; i < 5000; i++) { const v = 150 + rngTexture() * 100 | 0; g.fillStyle = `rgb(${v},${v},${v})`; g.fillRect(rngTexture() * n, rngTexture() * n, 1 + rngTexture() * 2, 1 + rngTexture() * 2); } }),
    block: () => texture(256, (g, n) => { g.fillStyle = '#8c8c88'; g.fillRect(0, 0, n, n); const bw = n / 3, bh = n / 6; for (let j = 0; j < 6; j++) for (let i = -1; i < 4; i++) { const v = 205 + (rngTexture() - 0.5) * 36 | 0; g.fillStyle = `rgb(${v},${v},${v - 4})`; g.fillRect(i * bw + (j % 2) * bw / 2 + 3, j * bh + 3, bw - 6, bh - 6); } }),
    tile: () => texture(128, (g, n) => { g.fillStyle = '#d8d8d8'; g.fillRect(0, 0, n, n); for (let j = 0; j < 8; j++) { g.fillStyle = 'rgba(0,0,0,0.30)'; g.fillRect(0, j * n / 8, n, 3); for (let i = 0; i < 6; i++) { g.fillStyle = 'rgba(0,0,0,0.16)'; g.fillRect(i * n / 6 + (j % 2) * n / 12, j * n / 8, 2, n / 8); } } }),
    dirt: () => texture(256, (g, n) => { g.fillStyle = '#86694a'; g.fillRect(0, 0, n, n); const r = rngTexture; for (let i = 0; i < 260; i++) { const v = 105 + r() * 60 | 0, x = r() * n, y = r() * n, q = 2 + r() * 9; g.fillStyle = `rgba(${v + 20},${v * 0.78 | 0},${v * 0.55 | 0},${0.10 + r() * 0.16})`; for (const dx of [-n, 0, n]) for (const dy of [-n, 0, n]) { g.beginPath(); g.arc(x + dx, y + dy, q, 0, 6.3); g.fill(); } } for (let i = 0; i < 2400; i++) { const v = 70 + r() * 120 | 0; g.fillStyle = `rgba(${v},${v * 0.8 | 0},${v * 0.6 | 0},0.5)`; const x = r() * n, y = r() * n; g.fillRect(x, y, 1 + r() * 2, 1 + r() * 2); if (x > n - 3) g.fillRect(x - n, y, 2, 2); if (y > n - 3) g.fillRect(x, y - n, 2, 2); } }),
    grass: () => texture(256, (g, n) => { g.fillStyle = '#9ccb62'; g.fillRect(0, 0, n, n); const r = rngTexture; for (let i = 0; i < 70; i++) { g.fillStyle = `rgba(${r() < 0.5 ? '200,225,110' : '90,150,60'},${0.10 + r() * 0.12})`; const x = r() * n, y = r() * n, q = 8 + r() * 24; for (const dx of [-n, 0, n]) for (const dy of [-n, 0, n]) { g.beginPath(); g.arc(x + dx, y + dy, q, 0, 6.3); g.fill(); } } for (let i = 0; i < 1400; i++) { g.strokeStyle = `hsl(${78 + r() * 30},${45 + r() * 25}%,${42 + r() * 24}%)`; g.lineWidth = 1; const x = r() * n, y = r() * n; g.beginPath(); g.moveTo(x, y); g.lineTo(x + (r() - 0.5) * 5, y - 3 - r() * 6); g.stroke(); } }),
    asphalt: () => texture(256, (g, n) => { g.fillStyle = '#9a9ea4'; g.fillRect(0, 0, n, n); for (let i = 0; i < 3500; i++) { const v = 110 + rngTexture() * 90 | 0; g.fillStyle = `rgb(${v},${v},${v + 4})`; g.fillRect(rngTexture() * n, rngTexture() * n, 1 + rngTexture() * 2, 1 + rngTexture() * 2); } }),
    sidewalk: () => texture(256, (g, n) => { g.fillStyle = '#9d9a92'; g.fillRect(0, 0, n, n); const q = n / 4; for (let j = 0; j < 4; j++) for (let i = 0; i < 4; i++) { const v = 214 + (rngTexture() - 0.5) * 20 | 0; g.fillStyle = `rgb(${v},${v - 3},${v - 10})`; g.fillRect(i * q + 2, j * q + 2, q - 4, q - 4); } }),
    fiber_cement: () => texture(128, (g, n) => { for (let i = 0; i < 8; i++) { const gr = g.createLinearGradient(i * n / 8, 0, (i + 1) * n / 8, 0); gr.addColorStop(0, '#f2f2f2'); gr.addColorStop(0.5, '#cfcfcf'); gr.addColorStop(1, '#f2f2f2'); g.fillStyle = gr; g.fillRect(i * n / 8, 0, n / 8, n); } }),
  };
  const TEX = {};
  for (const k of Object.keys(TEXGEN)) TEX[k] = (cfg.textures && cfg.textures[k]) || TEXGEN[k]();
   // app textures (cfg.textures) replace the procedural ones
  const ATLAS = {};
  Object.assign(K, { texture, rngTexture, TEXGEN, TEX, ATLAS });
}
